"use client";

import { useEffect, useState } from "react";
import "./style.css";
import "./page.css";
import { Cocktail } from "@/types";
import { CocktailCajita } from "@/components/cocktails/cocktailInfo";
import { getAllCocktails, getCocktailByName } from "@/lib/api/cocktail";
import { ocktailList } from "@/components/cocktails/cocktailList";

const Main = () => {
  const [search, setSearch] = useState("");
  const [cocktails, setCocktails] = useState<Cocktail[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    getAllCocktails()
      .then((res) => {
        const sorted = res.sort((a: Cocktail, b: Cocktail) =>
          a.strDrink.localeCompare(b.strDrink),
        );
        setCocktails(sorted);
      })
      .catch((e) => {
        setError(`Error cargando los datos: ${e.message}`);
      })
      .finally(() => {
        setLoading(false);
      });
  }, []);

  const filtrados = cocktails.filter((c) =>
    c.strDrink.toLowerCase().includes(search.toLowerCase()),
  );

  return (
    <div className="mainContainer">
      <h1 className="tituloPrincipal">Encuentra tu Cocktail</h1>
      <h2 className="subtitulo">By Sarah Rojas</h2>

      <input
        type="text"
        placeholder="Buscar cocktail..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
      />

    <CocktailList cocktails={filtrados.slice(0, visibleCount)} />

      {loading && <h2>Loading...</h2>}
      {error && <h2>{error}</h2>}

      <div className="cocktailsContainer">
        {filtrados.length > 0
          ? filtrados.map((c) => (
              <CocktailCajita key={c.strDrink} cocktail={c} />
            ))
          : !loading && (
              <p className="noResultados">No se han encontrado paises</p>
            )}
      </div>
    </div>
  );
};

export default Main;
